        if self.pending_resume:
            self.pending_resume = self.recovering = False
            self.stats['recovered_ranges'] += 1
            self.stats['failover_successes'] += 1
            self.report('grid_frame_gap_recovered')
            self.report('parent_failover_succeeded')


