class _sg_stream_BoundedBuffer:

    def __init__(self, capacity, timeout):
        if not 188 <= capacity <= 16 << 20 or timeout <= 0:
            raise ValueError('buffer configuration invalid')
        self.capacity = capacity
        self.timeout = timeout
        self.data = bytearray()
        self.condition = _sg_stream_threading.Condition()
        self.eof = False
        self.cancelled = False
        self.error = None
        self.peak_bytes = 0

    def put(self, data):
        view = memoryview(data)
        while view:
            deadline = _sg_stream_time.monotonic() + self.timeout
            with self.condition:
                while len(self.data) >= self.capacity and (not self.cancelled):
                    remaining = deadline - _sg_stream_time.monotonic()
                    if remaining <= 0:
                        raise _sg_stream_GridError('buffer_backpressure_timeout')
                    self.condition.wait(remaining)
                if self.cancelled:
                    raise _sg_stream_Cancelled('reader_closed')
                n = min(len(view), self.capacity - len(self.data))
                self.data.extend(view[:n])
                self.peak_bytes = max(self.peak_bytes, len(self.data))
                view = view[n:]
                self.condition.notify_all()

    def finish(self, error=None):
        with self.condition:
            self.error = error
            self.eof = True
            self.condition.notify_all()

    def wait_ready(self):
        with self.condition:
            self._wait()

    def _wait(self):
        deadline = _sg_stream_time.monotonic() + self.timeout
        while not self.data and (not self.eof) and (not self.cancelled):
            remaining = deadline - _sg_stream_time.monotonic()
            if remaining <= 0:
                raise _sg_stream_StreamError('Grid read timed out')
            self.condition.wait(remaining)
        if not self.data and self.error and (not self.cancelled):
            raise self.error

    def read(self, size):
        if size == 0:
            return b''
        with self.condition:
            self._wait()
            n = min(size if size >= 0 else self.capacity, len(self.data))
            data = bytes(self.data[:n])
            del self.data[:n]
            self.condition.notify_all()
            return data

    def close(self):
        with self.condition:
            self.cancelled = True
            self.data.clear()
            self.condition.notify_all()

def _sg_stream_receive(config, network, emit, report, stats):
    session = credentials = sink = None
    try:
        session = _sg_stream_bootstrap(config, report, http_factory=lambda: _sg_stream_HTTP(network.stop))
        credentials = _sg_stream_obtain_certificate(network, session, report)
        parents, node_key = _sg_stream_discover_parent(network, session.center, credentials, report)
        sink = _sg_stream_MediaSink(emit, config.capture_dir)
        _sg_stream_receive_media(network, parents, session.bno, node_key, sink, report, config.duration, rediscover=lambda: _sg_stream_discover_parent(network, session.center, credentials, report))
        if not sink.mux.video_frames:
            raise _sg_stream_GridError('no_playable_grid_video')
    finally:
        try:
            if sink:
                sink.close()
                stats.update(sink.stats)
        finally:
            if credentials:
                credentials.clear()
            if session:
                session.clear()
            config.clear()
            network.close()

class _sg_stream_SoopGridReader(_sg_stream_StreamIO):

    def __init__(self, stream, runner=_sg_stream_receive):
        super().__init__()
        self.stream = stream
        self.network = _sg_stream_Network()
        self.buffer = _sg_stream_BoundedBuffer(stream.buffer_size, stream.timeout)
        self.runner = runner
        self.thread = None
        self.stats = {}
        self.stages = []
        self._close_lock = _sg_stream_threading.Lock()
        self._closing = False

    def open(self):
        if self.thread is not None or self.closed:
            raise _sg_stream_StreamError('Grid reader already opened or closed')
        self.thread = _sg_stream_threading.Thread(target=self._run, name='soop-grid-receiver', daemon=True)
        self.thread.start()
        try:
            self.buffer.wait_ready()
        except Exception:
            self.close()
            raise
        return self

    def _run(self):
        error = None
        try:
            self.runner(self.stream.config, self.network, self.buffer.put, self.stages.append, self.stats)
        except Exception as exc:
            code = str(exc) if isinstance(exc, _sg_stream_GridError) else 'receiver_internal_failure'
            if not self._closing:
                error = _sg_stream_StreamError('SOOP Grid: ' + code)
        finally:
            self.network.close()
            self.buffer.finish(error)

    def readable(self):
        return not self.closed

    def read(self, size=-1):
        if self.closed or self._closing:
            return b''
        try:
            return self.buffer.read(size)
        except _sg_stream_StreamError as exc:
            self.close()
            raise OSError(str(exc)) from None

    def readinto(self, b):
        data = self.read(len(b))
        b[:len(data)] = data
        return len(data)

    def close(self):
        with self._close_lock:
            if self.closed:
                return
            self._closing = True
            self.network.close()
            self.buffer.close()
        if self.thread and self.thread is not _sg_stream_threading.current_thread():
            self.thread.join(12)
        self.stream.config.clear()
        super().close()

class _sg_stream_SoopGridStream(_sg_stream_Stream):
    __shortname__ = 'grid'

    def __init__(self, session, config):
        super().__init__(session)
        self.config = config
        self.buffer_size = min(max(int(session.get_option('ringbuffer-size') or 8 << 20), 188), 16 << 20)
        self.timeout = float(session.get_option('stream-timeout') or 60)
        self._opened = False

    def open(self):
        if self._opened:
            raise _sg_stream_StreamError('Grid streams are single-session; enumerate again to reopen')
        self._opened = True
        return _sg_stream_SoopGridReader(self).open()


